    @Override public void setupAnim(EntityEldritchGuardian entity,float walk,float amount,float age,float yaw,float pitch) {
        part("Hood1").yRot=yaw/57.295776F; part("Hood1").xRot=pitch/57.295776F;
        part("ArmL1").xRot=-1-entity.armLiftL+Mth.sin((age+20)/10)*.08F;
        part("ArmR1").xRot=-1-entity.armLiftR+Mth.sin(age/10)*.08F;
        part("LegpanelC1").xRot=-.15F+Mth.sin(age/8)*.12F;
        part("LegpanelC2").xRot=Mth.sin((age-5)/8)*.13F;
        part("LegpanelC3").xRot=Mth.sin((age-10)/8)*.14F;
        part("Cloak1").xRot=.2F+Mth.sin(age/7)*.08F;
        part("Cloak2").xRot=Mth.sin((age-5)/7)*.1F;
        part("Cloak3").xRot=Mth.sin((age-10)/7)*.12F;
        part("SidepanelL2").zRot=-.2F+Mth.sin((age+10)/8)*.12F;
        part("SidepanelL3").zRot=Mth.sin((age+5)/8)*.13F;
        part("SidepanelL4").zRot=Mth.sin(age/8)*.14F;
        part("SidepanelR2").zRot=.2F+Mth.sin((age-5)/8)*.12F;
        part("SidepanelR3").zRot=Mth.sin((age-10)/8)*.13F;
        part("SidepanelR4").zRot=Mth.sin((age-15)/8)*.14F;
    }
    @Override public void renderToBuffer(PoseStack pose,VertexConsumer out,int light,int overlay,int color) { root.render(pose,out,light,overlay,color); }
